module.exports = {
  env: {
    browser: true,
    es2021: true,
    node: true,
  },
  extends: [
    'eslint:recommended',
    '@docusaurus'
  ],
  parserOptions: {
    ecmaFeatures: {
      jsx: true,
    },
    ecmaVersion: 12,
    sourceType: 'module',
  },
  plugins: [
    'react',
  ],
  rules: {
    'no-console': 'warn',
    'no-unused-vars': 'warn',
    'no-undef': 'error',
    'no-duplicate-imports': 'error',
    'prefer-const': 'error',
    'no-var': 'error',
    'object-shorthand': 'error',
    'prefer-template': 'error',
    'no-useless-escape': 'off', // Docusaurus markdown often needs escapes
  },
  settings: {
    react: {
      version: 'detect',
    },
  },
  overrides: [
    {
      files: ['**/*.md', '**/*.mdx'],
      rules: {
        'no-undef': 'off', // Allow global variables in MD/MDX files
      },
    },
  ],
};

import js from '@eslint/js';
import docusaurus from '@docusaurus/eslint-plugin';
import reactRecommended from 'eslint-plugin-react/configs/recommended.js';

export default [
  js.configs.recommended,
  docusaurus.configs.recommended,
  reactRecommended,
  {
    languageOptions: {
      ecmaVersion: 12,
      sourceType: 'module',
      globals: {
        browser: true,
        node: true,
      },
      parserOptions: {
        ecmaFeatures: {
          jsx: true,
        },
      },
    },
    plugins: {
      react: await import('eslint-plugin-react'),
    },
    rules: {
      'no-console': 'warn',
      'no-unused-vars': 'warn',
      'no-undef': 'error',
      'no-duplicate-imports': 'error',
      'prefer-const': 'error',
      'no-var': 'error',
      'object-shorthand': 'error',
      'prefer-template': 'error',
      'no-useless-escape': 'off', // Docusaurus markdown often needs escapes
    },
    settings: {
      react: {
        version: 'detect',
      },
    },
    files: ['**/*.md', '**/*.mdx'],
    rules: {
      'no-undef': 'off', // Allow global variables in MD/MDX files
    },
  },
];

