/**
 * Split document content into chunks for embedding
 * @param {string} content - Document content to split
 * @param {number} chunkSize - Maximum chunk size in characters (default 1000)
 * @param {number} overlap - Overlap between chunks in characters (default 200)
 * @returns {Array<string>} Array of content chunks
 */
export function chunkDocument(content, chunkSize = 1000, overlap = 200) {
  const chunks = [];
  const paragraphs = content.split(/\n\s*\n/); // Split by paragraph breaks

  let currentChunk = '';

  for (const paragraph of paragraphs) {
    // If adding this paragraph would exceed chunk size
    if (currentChunk.length + paragraph.length > chunkSize && currentChunk.length > 0) {
      // Save current chunk
      chunks.push(currentChunk.trim());

      // Start new chunk with overlap from previous chunk
      if (overlap > 0) {
        const overlapText = currentChunk.slice(-overlap);
        currentChunk = overlapText + paragraph;
      } else {
        currentChunk = paragraph;
      }
    } else {
      currentChunk += (currentChunk ? '\n\n' : '') + paragraph;

      // If current chunk is getting too large, split it by sentences
      if (currentChunk.length > chunkSize) {
        const sentences = currentChunk.match(/[^\.!?]+[\.!?]+/g) || [currentChunk];
        let tempChunk = '';

        for (const sentence of sentences) {
          if (tempChunk.length + sentence.length > chunkSize && tempChunk.length > 0) {
            chunks.push(tempChunk.trim());
            tempChunk = sentence;
          } else {
            tempChunk += sentence;
          }
        }

        currentChunk = tempChunk;
      }
    }
  }

  // Add the last chunk if it has content
  if (currentChunk.trim().length > 0) {
    chunks.push(currentChunk.trim());
  }

  return chunks;
}

export default {
  parseTextbookDocuments,
  createMarkdownProcessor,
  chunkDocument
};

